{
  "items": [
    {
      "name": "MvPolynomial.degreeOf_mul_X_self",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (j : σ) (f : MvPolynomial σ R),\n  MvPolynomial.degreeOf j (f * MvPolynomial.X j) ≤ MvPolynomial.degreeOf j f + 1"
    },
    {
      "name": "Polynomial.degree_derivative_le",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, (Polynomial.derivative p).degree ≤ p.degree"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_X_of_ne",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {i j : σ} (f : MvPolynomial σ R),\n  i ≠ j → MvPolynomial.degreeOf i (f * MvPolynomial.X j) = MvPolynomial.degreeOf i f"
    },
    {
      "name": "MvPolynomial.degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → σ → MvPolynomial σ R → ℕ"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [IsAddTorsionFree R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree = p.natDegree - n"
    }
  ]
}

{
  "items": [
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "MvPolynomial.mkDerivation_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Derivation",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (R : Type u_2) {A : Type u_3} [inst : CommSemiring R] [inst_1 : AddCommMonoid A] [inst_2 : Module R A]\n  [inst_3 : Module (MvPolynomial σ R) A] [inst_4 : IsScalarTower R (MvPolynomial σ R) A] (f : σ → A) (s : σ →₀ ℕ)\n  (r : R),\n  (MvPolynomial.mkDerivation R f) ((MvPolynomial.monomial s) r) =\n    r • s.sum fun i k => (MvPolynomial.monomial (s - Finsupp.single i 1)) ↑k • f i"
    },
    {
      "name": "MvPolynomial.pderiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type v} → [inst : CommSemiring R] → σ → Derivation R (MvPolynomial σ R) (MvPolynomial σ R)"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "MvPolynomial.pderiv_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} {a : R} {s : σ →₀ ℕ} [inst : CommSemiring R] {i : σ},\n  (MvPolynomial.pderiv i) ((MvPolynomial.monomial s) a) = (MvPolynomial.monomial (s - Finsupp.single i 1)) (a * ↑(s i))"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPolynomial.degreeOf_coeff_finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {n : ℕ} (p : MvPolynomial (Fin (n + 1)) R) (j : Fin n) (i : ℕ),\n  MvPolynomial.degreeOf j (((MvPolynomial.finSuccEquiv R n) p).coeff i) ≤ MvPolynomial.degreeOf j.succ p"
    },
    {
      "name": "MvPolynomial.monomial_le_degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) {f : MvPolynomial σ R} {m : σ →₀ ℕ},\n  m ∈ f.support → m i ≤ MvPolynomial.degreeOf i f"
    },
    {
      "name": "Polynomial.coeff_X_pow_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n d : ℕ), (Polynomial.X ^ n * p).coeff (d + n) = p.coeff d"
    },
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "MvPolynomial.totalDegree_sub_C_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommRing R] (p : MvPolynomial σ R) (r : R),\n  (p - MvPolynomial.C r).totalDegree ≤ p.totalDegree"
    }
  ]
}
